#!/usr/bin/env bash
# Runs the PC test suites (no iPod, no root, nothing downloaded; every ROM is generated by the tests).
#   tests/run_tests.sh [--sdk /path/to/NanoApps]
# Without --sdk the front-end suite (run_ui_tests.sh) is skipped, because it needs the SDK headers.
set -uo pipefail
HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
REPO=$(dirname "$HERE")
SDK=
while [[ $# -gt 0 ]]; do
  case $1 in
    --sdk) SDK=${2:-}; shift 2;;
    *) echo "usage: $0 [--sdk NANOAPPS_DIR]" >&2; exit 2;;
  esac
done
W=$(mktemp -d); trap 'rm -rf "$W"' EXIT
rc=0

echo "### core: synthetic ARM / Thumb programs"
gcc -O1 -Wall -I"$REPO/src" -o "$W/core_test" "$HERE/core_test.c" \
    "$REPO/src/cpu.c" "$REPO/src/mem.c" "$REPO/src/ppu.c" "$REPO/src/bios.c" || exit 1
"$W/core_test" || rc=1

echo "### prepare_rom.py on synthetic ROMs"
P=$REPO/tools/prepare_rom.py; M=$HERE/mkrom.py
python3 "$M" "$W/a.gba" 100000 --save flash128
python3 "$P" "$W/a.gba" --name demo_one --out "$W/out" > "$W/p1.log" 2>&1 || { cat "$W/p1.log"; rc=1; }
ok() { if eval "$2"; then echo "[PASS] $1"; else echo "[FAIL] $1"; rc=1; fi; }
ok "prepare_rom: 100000 bytes -> 4 pages + meta.bin" "[ \$(ls $W/out/demo_one | wc -l) = 5 ] && [ \$(stat -c %s $W/out/demo_one/meta.bin) = 8 ]"
ok "prepare_rom: size and Flash128 save type in meta.bin" "[ \"\$(od -An -tu4 -N4 $W/out/demo_one/meta.bin | tr -d ' ')\" = 100000 ] && [ \"\$(od -An -tu1 -j4 -N1 $W/out/demo_one/meta.bin | tr -d ' ')\" = 3 ]"
ok "prepare_rom: pages reassemble to the ROM" "[ \"\$(cat $W/out/demo_one/p00[0-3].bin | head -c 100000 | sha1sum)\" = \"\$(sha1sum < $W/a.gba)\" ]"
python3 "$P" "$W/a.gba" --name demo_one --out "$W/out" > /dev/null 2>&1
ok "prepare_rom: existing folder refused without --force" "[ \$? != 0 ]"
python3 "$P" "$W/a.gba" --name "Bad Name" --out "$W/out" > /dev/null 2>&1
ok "prepare_rom: invalid name refused" "[ \$? != 0 ]"
head -c $((32*1024*1024 + 4096)) /dev/zero > "$W/big.gba"
python3 "$P" "$W/big.gba" --name too_big --out "$W/out" > /dev/null 2>&1
ok "prepare_rom: ROM over 32 MiB refused" "[ \$? != 0 ]"

if [[ -n $SDK ]]; then
  echo "### front end (menu, saves, cache, memory release)"
  "$HERE/run_ui_tests.sh" --sdk "$SDK" || rc=1
else
  echo "(front-end suite skipped: pass --sdk /path/to/NanoApps)"
fi
echo "run_tests: $([ $rc = 0 ] && echo PASS || echo FAIL)"
exit $rc
